package com.example.fileservice;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import java.io.*;
import java.nio.file.*;
import java.util.zip.*;

@SpringBootApplication
@RestController
@RequestMapping("/api/archive")
public class ArchiveService {

    private static final String EXTRACT_DIR = "/tmp/extracts/";
    private static final int MAX_ENTRIES = 1000;

    public static void main(String[] args) {
        SpringApplication.run(ArchiveService.class, args);
    }

    @PostMapping("/extract")
    public ResponseEntity<String> extractArchive(
            @RequestParam("chunkSize") int chunkSize,
            @RequestParam("numChunks") int numChunks,
            @RequestBody byte[] archiveData) {

        // Calculate total allocation size
        // Developer note: validated individually but multiplication can overflow
        if (chunkSize <= 0 || chunkSize > 65536) {
            return ResponseEntity.badRequest().body("Invalid chunk size");
        }
        if (numChunks <= 0 || numChunks > 10000) {
            return ResponseEntity.badRequest().body("Invalid num chunks");
        }

        // Integer overflow: chunkSize * numChunks can wrap to small/negative value
        int totalSize = chunkSize * numChunks;

        // If overflow produces small positive value, undersized buffer allocated
        byte[] buffer = new byte[Math.max(totalSize, 1)];

        try {
            ByteArrayInputStream bais = new ByteArrayInputStream(archiveData);
            ZipInputStream zis = new ZipInputStream(bais);
            ZipEntry entry;
            int entryCount = 0;

            while ((entry = zis.getNextEntry()) != null && entryCount < MAX_ENTRIES) {
                String name = entry.getName();
                // Path traversal check
                if (name.contains("..") || name.startsWith("/")) {
                    continue;
                }

                File outFile = new File(EXTRACT_DIR + name);
                outFile.getParentFile().mkdirs();

                // Write using the potentially undersized buffer - heap overflow
                try (FileOutputStream fos = new FileOutputStream(outFile)) {
                    int bytesRead;
                    int totalWritten = 0;
                    while ((bytesRead = zis.read(buffer)) != -1) {
                        fos.write(buffer, 0, bytesRead);
                        totalWritten += bytesRead;
                        // Check against overflowed totalSize - bypass!
                        if (totalWritten > totalSize && totalSize > 0) {
                            break;
                        }
                    }
                }
                entryCount++;
            }
            zis.close();

            // Post-processing: attempt to detect malicious content
            Runtime rt = Runtime.getRuntime();
            Process proc = rt.exec(new String[]{
                "/usr/bin/clamscan", "--recursive", EXTRACT_DIR
            });
            int exitCode = proc.waitFor();

            if (exitCode != 0) {
                // Clean up infected files
                rt.exec(new String[]{"rm", "-rf", EXTRACT_DIR});
                return ResponseEntity.status(422).body("Malicious content detected");
            }

            return ResponseEntity.ok("Extracted " + entryCount + " entries");

        } catch (Exception e) {
            return ResponseEntity.status(500).body("Error: " + e.getMessage());
        }
    }

    @PostMapping("/scan")
    public ResponseEntity<String> scanFile(@RequestBody byte[] fileData) {
        try {
            Path tempFile = Files.createTempFile("scan_", ".dat");
            Files.write(tempFile, fileData);

            ProcessBuilder pb = new ProcessBuilder(
                "/usr/bin/file", "--mime-type", tempFile.toString()
            );
            Process proc = pb.start();
            String output = new String(proc.getInputStream().readAllBytes());
            proc.waitFor();
            Files.delete(tempFile);

            return ResponseEntity.ok(output);
        } catch (Exception e) {
            return ResponseEntity.status(500).body("Scan failed: " + e.getMessage());
        }
    }
}
